INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('e52ab5fa-bf03-50a4-be14-989bd96ea908', '07bc635c-46e7-5c3c-a535-3c07fbec04b9', 29, '“หากสิ่งมีชีวิตทิ้งร่องรอยการเดินไว้ เมื่อเวลาผ่านไปเป็นระยะเวลานาน ร่องรอยจะถูกฝังไว้ใต้ชั้นตะกอน จากนั้นร่องรอยจะกลายเป็นหิน” จากข้อความข้อใดกล่าวถูกต้อง', NULL, 'multiple_choice', 1);
