INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('51c62956-8fd8-5dcd-a322-1c95090c4b7d', '07bc635c-46e7-5c3c-a535-3c07fbec04b9', 30, 'พิจารณาบทสนทนาต่อไปนี้ จิน : ทองคำเป็นแร่ประกอบหินที่สามารถนำไฟฟ้าได้จึงนิยมนำมาใช้ทำสายไฟ เจน : จริงเหรอ แสดงว่าถ้าเราเอาทองคำไปแหย่ปลั๊กไฟก็มีโอกาสโดนไฟดูดน่ะสิ จูน : แต่เรารู้ว่าทองคำมีความเหนียวสามารถยืดเป็นเส้นได้ เค้าเลยเอามาทำเครื่องประดับกัน จากบทสนทนาใครกล่าวถึงทองคำได้ถูกต้อง', NULL, 'multiple_choice', 1);
